import { NeuroNoise, type NeuroNoiseProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ShaderNeuroNoiseProps
  extends Omit<NeuroNoiseProps, "frame" | "ref"> {}

function ShaderNeuroNoiseBase({
  speed = 1,
  colorFront = "#8a8a95",
  colorMid = "#4a4a68",
  colorBack = "#12121a",
  brightness = 0.05,
  contrast = 0.3,
  className,
  ...rest
}: ShaderNeuroNoiseProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-neuro-noise"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <NeuroNoise
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorFront={colorFront}
        colorMid={colorMid}
        colorBack={colorBack}
        brightness={brightness}
        contrast={contrast}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  brightness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.05,
    description: "Brightness",
    hiddenFromList: false,
  },
  contrast: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.3,
    description: "Contrast",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  colorMid: {
    type: "color",
    default: "#4a4a68",
    description: "Mid",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","brightness","contrast","colorBack","colorMid"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  brightness: 0.05,
  contrast: 0.3,
  colorBack: "#12121a",
  colorMid: "#4a4a68",
};

type ShaderNeuroNoiseElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderNeuroNoiseBase>;

const ShaderNeuroNoiseInner = forwardRef<
  HTMLDivElement,
  ShaderNeuroNoiseElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderNeuroNoise>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderNeuroNoiseBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderNeuroNoiseBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderNeuroNoise = Interactive.withSchema({
  Component: ShaderNeuroNoiseInner,
  componentName: "<ShaderNeuroNoise>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
